 *
 * <p>On success the authenticated identity is published as the request
 * attributes {@link #ATTR_USER_ID}, {@link #ATTR_USERNAME} and
 * {@link #ATTR_ROLE} for the downstream handler.</p>
 */
@Component
public class JwtFilter extends OncePerRequestFilter {

