import jakarta.servlet.ServletOutputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

import static com.dochub.platform.controller.DocumentController.currentRole;
import static com.dochub.platform.controller.DocumentController.currentUserId;
import static com.dochub.platform.controller.DocumentController.respond;

/**
 * File routes: multipart upload against a document, raw binary download, and
 * the two metadata-only listings (per document and platform-wide for ADMINs).
 */
@RestController
@RequestMapping("/api")
public class FileController {

    static final String DOC_NOT_FOUND = "文档不存在";
    static final String FILE_NOT_FOUND = "文件不存在";
    static final String FORBIDDEN = "权限不足";
    static final String EMPTY_FILE = "请选择文件";

    static final String ROLE_ADMIN = "ADMIN";
    static final String DEFAULT_CONTENT_TYPE = "application/octet-stream";
    static final String JSON_CONTENT_TYPE = "application/json;charset=UTF-8";

    private final FileService fileService;

    private final DocumentService documentService;

    public FileController(FileService fileService, DocumentService documentService) {
        this.fileService = fileService;
        this.documentService = documentService;
    }

    /**
     * Uploads one multipart part named {@code file} onto document {@code docId}.
     *
     * <p>Controller-level pre-checks run in order — document missing (404),
     * caller neither owner nor ADMIN (403), empty part (400). Anything the
     * service itself rejects rides back inside an HTTP 200 response whose
     * envelope code carries the failure.</p>
     */
    @PostMapping("/documents/{docId}/files/upload")
    public ResponseEntity<ApiResponse<?>> upload(@PathVariable("docId") Long docId,
                                                 @RequestParam(value = "file", required = false) MultipartFile file,
                                                 HttpServletRequest httpRequest) {
        Document document = documentService.getDocumentById(docId);
        if (document == null) {
            return respond(404, ApiResponse.error(404, DOC_NOT_FOUND));
        }
        if (!canAccess(document, httpRequest)) {
            return respond(403, ApiResponse.error(403, FORBIDDEN));
        }
        if (file == null || file.isEmpty() || file.getSize() == 0) {
            return respond(400, ApiResponse.error(400, EMPTY_FILE));
        }
        ApiResponse<?> body = fileService.uploadFile(docId, file);
        return respond(200, body);
    }

    /**
     * Streams the stored bytes of one file record straight to the servlet
     * response; failures are written as JSON envelopes.
     */
    @GetMapping("/files/{id}")
    public void download(@PathVariable("id") Long id,
                         HttpServletRequest httpRequest,
                         HttpServletResponse response) throws IOException {
        FileRecord record = fileService.getFileById(id);
        if (record == null) {
            writeJsonError(response, 404, FILE_NOT_FOUND);
            return;
        }
        Document document = documentService.getDocumentById(record.getDocId());
        if (document == null) {
            writeJsonError(response, 404, FILE_NOT_FOUND);
            return;
        }
        if (!canAccess(document, httpRequest)) {
            writeJsonError(response, 403, FORBIDDEN);
            return;
        }

        byte[] data = record.getFileData() == null ? new byte[0] : record.getFileData();
        long size = record.getFileSize() == null ? data.length : record.getFileSize();
        if (size > data.length) {
            // Never promise more bytes than are actually written.
            size = data.length;
        }

        response.setStatus(HttpServletResponse.SC_OK);
        response.setContentType(contentTypeOf(record));
        response.setHeader("Content-Disposition", contentDispositionOf(record.getOriginalName()));
        response.setContentLengthLong(size);

        ServletOutputStream out = response.getOutputStream();
        out.write(data);
        out.flush();
    }

    /**
     * Metadata-only listing of one document's files.
     */
    @GetMapping("/documents/{docId}/files")
    public ResponseEntity<ApiResponse<?>> listDocumentFiles(@PathVariable("docId") Long docId,
                                                            HttpServletRequest httpRequest) {
        Document document = documentService.getDocumentById(docId);
        if (document == null) {
            return respond(404, ApiResponse.error(404, DOC_NOT_FOUND));
        }
        if (!canAccess(document, httpRequest)) {
            return respond(403, ApiResponse.error(403, FORBIDDEN));
        }
        return respond(200, fileService.getFilesByDocument(docId));
    }

    /**
     * Metadata-only listing of every file in the system; ADMIN only.
     */
    @GetMapping("/admin/files")
    public ResponseEntity<ApiResponse<?>> listAllFiles(HttpServletRequest httpRequest) {
        if (!ROLE_ADMIN.equals(currentRole(httpRequest))) {
            return respond(403, ApiResponse.error(403, FORBIDDEN));
        }
        return respond(200, fileService.getAllFiles());
    }

    private boolean canAccess(Document document, HttpServletRequest request) {
        return documentService.canAccess(document, currentUserId(request), currentRole(request));
    }

    private static String contentTypeOf(FileRecord record) {
        String contentType = record.getContentType();
        if (contentType == null || contentType.trim().isEmpty()) {
            return DEFAULT_CONTENT_TYPE;
        }
        return contentType;
    }

    /**
     * {@code Content-Disposition} marking the body as an attachment bearing the
     * record's original filename.
     *
     * <p>Header values must stay pure ASCII: the container discards a header
     * altogether when its value carries anything else, which would lose the
     * attachment marking with it. Names outside printable ASCII therefore go
     * out percent-encoded, both as an ASCII {@code filename} fallback and in the
     * RFC 5987 {@code filename*} form that lets conforming clients recover the
     * original name.</p>
     */
    private static String contentDispositionOf(String originalName) {
        String name = (originalName == null || originalName.isEmpty()) ? "download" : originalName;
        if (isHeaderSafe(name)) {
            String quoted = name.replace("\\", "\\\\").replace("\"", "\\\"");
            return "attachment; filename=\"" + quoted + "\"";
        }
        String encoded = URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20");
        return "attachment; filename=\"" + encoded + "\"; filename*=UTF-8''" + encoded;
    }

    /**
     * @return {@code true} when every character is printable ASCII and can be
     *         written into a header value as-is.
     */
    private static boolean isHeaderSafe(String value) {
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c < 0x20 || c > 0x7E) {
                return false;
            }
        }
        return true;
    }

    /**
     * Writes a hand-built JSON error envelope with an explicit status code.
     */
    private static void writeJsonError(HttpServletResponse response, int status, String message) throws IOException {
        response.setStatus(status);
        response.setContentType(JSON_CONTENT_TYPE);
        response.setCharacterEncoding("UTF-8");
        OutputStream body = response.getOutputStream();
        body.write(("{\"code\":" + status + ",\"message\":\"" + message + "\",\"data\":null}")
                .getBytes(StandardCharsets.UTF_8));
        body.flush();
    }
}

package com.dochub.platform.dto;

/**
 * Uniform JSON envelope returned by every API route.
 *
 * <pre>{"code": &lt;int&gt;, "message": &lt;string&gt;, "data": &lt;object|array|null&gt;}</pre>
 *
 * @param <T> the payload type carried in {@code data}
 */
public class ApiResponse<T> {

    /** Business/HTTP style status code carried inside the envelope. */
    private int code;

    /** Human readable message; {@code "success"} for the default factory. */
    private String message;

    /** Payload object, array or {@code null} (always {@code null} on errors). */
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    /**
     * Successful envelope with the default {@code "success"} message.
     */
    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(200, "success", data);
    }

    /**
     * Successful envelope carrying a custom message.
     */
    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    /**
     * Failure envelope; {@code data} is always {@code null}.
     */
    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }

    public int getCode() {
        return code;
    }

    public void setCode(int code) {
        this.code = code;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public T getData() {
        return data;
    }

    public void setData(T data) {
        this.data = data;
    }
}

